// Checkout handler with revenue conversion fix
const { logEvent } = require('../monitoring/eventLogger');
const { getPricing } = require('../pricing/pricingModule');

async function handleCheckout(req, res) {
  try {
    const { offerId, userId, paymentMethod } = req.body;
    if (!offerId || !userId) {
      return res.status(400).json({ error: 'Missing required fields' });
    }
    // Fetch pricing for the offer
    const pricing = await getPricing(offerId);
    if (!pricing || pricing.error) {
      return res.status(500).json({ error: 'Pricing unavailable' });
    }
    // Simulate payment processing (replace with real gateway)
    const paymentSuccess = true; // Placeholder
    if (paymentSuccess) {
      // Log paid event
      await logEvent('paidEvent', { offerId, userId, amount: pricing.amount, currency: pricing.currency });
      return res.status(200).json({ status: 'success', transactionId: 'txn_' + Date.now() });
    } else {
      return res.status(402).json({ error: 'Payment failed' });
    }
  } catch (err) {
    console.error('Checkout error:', err);
    return res.status(500).json({ error: 'Internal server error' });
  }
}

module.exports = { handleCheckout };
